import {recordEvidence} from './journey.js';
import {arrangeObservationWorkspace} from './lesson-views.js';
import {benchArtwork,dailyMaterial} from './lesson-materials.js';

export const dailyLessonData={
 life:{tab:'光合與呼吸',title:'方向不同，都有氧化與還原',intro:'光合作用把光能存進養分；有氧呼吸釋出養分中的能量。兩個過程各自都同時包含氧化與還原，並不是一個只氧化、另一個只還原。',source:[['OpenStax・光合作用','https://openstax.org/books/microbiology/pages/8-6-photosynthesis'],['耶魯大學・光合與呼吸','https://watermanagement.yale.edu/topics/water-science/introduction-to-water-quality/photosynthesis-and-respiration/']]},
 rust:{tab:'鐵釘生鏽',title:'慢慢生鏽，也有一對反應',intro:'潮濕空氣中的鐵緩慢氧化。沒有火焰，不代表沒有氧化還原。',equation:'4Fe + 3O₂ → 2Fe₂O₃',note:'以 Fe₂O₃ 表示的總反應簡式；實際鐵鏽包含水合氧化物等成分。',oxidation:['鐵 Fe','成為鐵鏽中的鐵化合物'],reduction:['氧氣 O₂','成為鐵鏽中的含氧成分'],action:'觀察一段時間後',caption:'鐵被氧化的同時，氧被還原。水與氧共同促進一般條件下的生鏽。'},
 warmer:{tab:'暖暖包',title:'鐵粉氧化，把熱送出來',intro:'暖暖包中的鐵粉與氧反應，放出熱。鐵粉表面積大，水與鹽等成分也會影響反應。',equation:'4Fe + 3O₂ → 2Fe₂O₃ ＋ 熱',note:'氧化產物的簡化表示；暖暖包中的實際產物可能含水。',oxidation:['鐵粉 Fe','形成氧化後的鐵化合物'],reduction:['氧氣 O₂','成為氧化產物中的含氧成分'],action:'拆開外袋，觀察放熱',caption:'鐵粉被氧化、氧被還原，兩者一起發生；暖暖包沒有火焰。'},
 cloth:{tab:'漂白衣服',title:'色素被氧化，漂白劑被還原',intro:'以含次氯酸鈉 NaClO 的氧化型漂白劑為例。它改變某些色素的結構，使污漬顏色變淡；不是把顏色「洗到水裡」而已。',equation:'色素 ＋ 氧化型漂白劑 → 氧化後的色素 ＋ 還原後的漂白劑',note:'反應角色示意，不是配平式；不同色素有不同產物。',oxidation:['污漬中的色素','被氧化，發色結構改變'],reduction:['漂白劑中的 ClO⁻','被還原，形成 Cl⁻ 等產物'],action:'播放衣物漂白',caption:'當色素被氧化時，漂白劑同時被還原。這裡模擬能被此漂白劑作用的一種污漬。',source:[['ACS・漂白劑的化學','https://www.acs.org/content/dam/acsorg/education/resources/highschool/chemmatters/gc-building-a-better-bleach.pdf']]},
 bamboo:{tab:'漂白竹筷',title:'還原型漂白：和衣物漂白比一比',intro:'竹材加工可能使用 SO₂ 等漂白處理。國中常將 SO₂ 列為還原型漂白劑，下面以「色素被還原」的概念模型比較兩種角色。',equation:'色素 ＋ 還原型漂白劑 → 還原後的色素 ＋ 氧化後的漂白劑',note:'還原型漂白的角色模型，不是所有竹材、色素的實際反應式。',oxidation:['還原型漂白劑','自身被氧化'],reduction:['可被還原的色素','被還原，發色結構改變'],action:'播放竹材脫色示意',caption:'在這個還原型漂白模型中，漂白劑被氧化、色素被還原，兩者同時發生。',caution:'只看到竹筷變白，還不能證明發生氧化還原。SO₂／亞硫酸鹽對某些色素也可能藉由加成反應（和色素結合、改變發色結構）脫色；不能把所有漂白都當成同一種反應。',source:[['環境部・SO₂ 與竹筷漂白','https://www.cha.gov.tw/cp-263-2710-e17a7-1.html'],['研究・亞硫酸鹽的加成脫色','https://doi.org/10.1016/S0040-4039(98)01205-2']]},
 vitaminC:{tab:'維他命 C',title:'抗氧化的維他命 C，自身會被氧化',intro:'切開的蘋果接觸空氣後，會因酵素作用逐漸變褐。維他命 C 可把醌類（褐變途徑中的中間物質）還原，延緩變色；它自己則被氧化。',equation:'維他命 C ＋ 醌類 → 氧化後的維他命 C ＋ 還原後的酚類',note:'反應角色示意；抗氧化效果受含量、時間與環境影響，並非永遠不變色。',oxidation:['維他命 C','氧化成脫氫抗壞血酸等產物'],reduction:['褐變途徑中的醌類','還原回酚類'],action:'比較放置後的蘋果',caption:'維他命 C 以自身被氧化，換來另一物質被還原。「抗氧化」不代表它自己不會氧化。',source:[['研究・蘋果褐變中的氧化還原','https://pmc.ncbi.nlm.nih.gov/articles/PMC3799748/'],['NIH・維他命 C','https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/']]},
 vitaminE:{tab:'維他命 E',title:'保護脂質，截斷氧化連鎖',intro:'維他命 E 是脂溶性的抗氧化物。自由基是容易與其他物質反應的粒子；維他命 E 可把氫原子交給脂質過氧自由基，減少它繼續攻擊脂質。',equation:'ROO• ＋ 維他命 E–H → ROOH ＋ 維他命 E•',note:'代表性反應簡式；ROO• 是脂質過氧自由基，• 表示未成對電子，不是氧原子。',oxidation:['維他命 E','提供氫原子，自身被氧化'],reduction:['脂質過氧自由基 ROO•','轉為 ROOH，截斷連鎖傳播'],action:'讓維他命 E 接住自由基',caption:'維他命 E 被氧化的同時，自由基被還原。它主要在脂質環境中作用，和水溶性的維他命 C 不同。',source:[['NIH・維他命 E','https://ods.od.nih.gov/factsheets/VitaminE-HealthProfessional/'],['研究・維他命 C、E 的氫原子轉移','https://pubmed.ncbi.nlm.nih.gov/1647978/']]}
};

function dailyRolePair(oxidation,reduction,active=true){
 return `<div class="daily-role-pair ${active?'roles-active':''}"><div class="role-oxidation"><span>被氧化</span><b>${oxidation[0]}</b><p>${oxidation[1]}</p></div><div class="daily-pair-link">同時<br>發生</div><div class="role-reduction"><span>被還原</span><b>${reduction[0]}</b><p>${reduction[1]}</p></div></div>`;
}

function dailySources(d){
 return d.source?``:'';
}

